import json, sys
data = json.load(sys.stdin)
json.dump(data, open('after-cpm-packages.json','w'), indent=2)

baseline = json.load(open('baseline-packages.json'))

def pkg_map(d):
    m = {}
    for p in d['projects']:
        proj = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                m[(proj, fw['framework'], pkg['id'])] = pkg['resolvedVersion']
    return m

before = pkg_map(baseline)
after = pkg_map(data)

all_keys = sorted(set(before) | set(after))
changes = []
unchanged = []
for k in all_keys:
    b = before.get(k)
    a = after.get(k)
    if b != a:
        changes.append((k, b, a))
    else:
        unchanged.append((k, a))

print('=== CHANGES ===')
for (proj,fw,pkg), b, a in changes:
    print(f'  {proj:20s} {fw:8s} {pkg:50s} {b or \"(none)\"} -> {a or \"(none)\"}')

print()
print(f'=== UNCHANGED ({len(unchanged)} entries) ===')
for (proj,fw,pkg), v in unchanged:
    print(f'  {proj:20s} {fw:8s} {pkg:50s} {v}')
"

